import type { ForkInfo } from "@shared/fork/types";
import type { Binder } from "../rpc/types";
import { getForkInfo } from "../fork";

/**
 * IPC channels owned by this fork.
 *
 * Mounted once from `registerRemoteHandlers` (`// FORK-MOUNT:M1`), which means
 * these channels work in **both** transports without extra work: in-process
 * Electron IPC in the desktop app, and gRPC when the desktop talks to a remote
 * backend (the client's proxy list is generated by running this same
 * registration — see `src/main/ipc/index.ts`).
 *
 * Channel naming: prefix everything with `fork:` so it can never collide with an
 * upstream channel that appears later.
 */
export function registerForkHandlers(bind: Binder): void {
  bind("fork:info", () => getForkInfo());
}

export type { ForkInfo };
